import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        int[] aliceChoices = Arrays.stream(scanner.nextLine().split(" "))
                                   .mapToInt(Integer::parseInt)
                                   .toArray();
        int[] bobChoices = Arrays.stream(scanner.nextLine().split(" "))
                                 .mapToInt(Integer::parseInt)
                                 .toArray();

        int[] shiftedBobChoices = new int[n];
        for (int i = 0; i < n; i++) {
            shiftedBobChoices[i] = bobChoices[(i + 1) % n];
        }

        int minWins = 0;
        int maxWins = 0;

        for (int i = 0; i < n; i++) {
            minWins += Math.min(aliceChoices[i], shiftedBobChoices[i]);
        }

        int maxBob = Arrays.stream(shiftedBobChoices).max().getAsInt();

        for (int i = 0; i < n; i++) {
            if (shiftedBobChoices[i] == maxBob && shiftedBobChoices[i] + aliceChoices[i] > minWins) {
                minWins = shiftedBobChoices[i] + aliceChoices[i];
            }
        }

        int maxAlice = Arrays.stream(aliceChoices).max().getAsInt();

        for (int i = 0; i < n; i++) {
            if (aliceChoices[i] == maxAlice && aliceChoices[i] + shiftedBobChoices[i] > minWins) {
                minWins = aliceChoices[i] + shiftedBobChoices[i];
            }
        }

        if (minWins > n) {
            minWins -= n;
        } else {
            minWins = 0;
        }

        System.out.println(minWins + " " + maxWins);
        scanner.close();
    }
}
